/*
 * A282146  Numbers n with k digits in base x (MSD(n)=d_k, LSD(n)=d_1) such
 *          that, chosen one of their digits in position d_k < j < d_1, is
 *          Sum_{i=j..k}{(i-j+1)*d_i} = Sum_{i=1..j-1}{(j-i)*d_i}. Case x = 5.
 * https://oeis.org/A282146
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   returns the n‑th base‑5 fulcrum number (A282146). The sequence
 *            is generated by brute‑force search and cached between calls. The
 *            function works for any seq_t/idx_t combination provided in the
 *            build environment
 * Range:     u8 n <= 33, u16 n <= 4530, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

#define MAX_DIGITS 30             /* maximum base‑5 digits handled */

/* Check whether an integer has the fulcrum property */
static bool is_fulcrum(idx_t val)
{
    if (val == 0) return false;   /* no digits */

    int digits[MAX_DIGITS];
    int k = 0;                      /* number of digits */

    /* Extract base‑5 digits, digits[1] is least significant */
    for (idx_t tmp = val; tmp; tmp /= 5) {
        if (k >= MAX_DIGITS) return false;  /* too many digits */
        digits[++k] = (int)(tmp % 5);
    }
    if (k < 2) return false;       /* need at least two digits */

    /* Prefix sums: prefD[i] = Σ d[t], prefId[i] = Σ t*d[t] */
    idx_t prefD[MAX_DIGITS + 1] = {0};
    idx_t prefId[MAX_DIGITS + 1] = {0};
    for (int i = 1; i <= k; ++i) {
        prefD[i]  = prefD[i - 1] + (idx_t)digits[i];
        prefId[i] = prefId[i - 1] + (idx_t)i * (idx_t)digits[i];
    }

    idx_t totalD  = prefD[k];
    idx_t totalId = prefId[k];

    for (int j = 2; j <= k; ++j) {
        idx_t PD  = prefD[j - 1];
        idx_t PId = prefId[j - 1];

        /* left side: Σ_{i=j..k} (i-j+1)*d_i  = j*PD - PId */
        idx_t left = (idx_t)j * PD - PId;

        /* right side: Σ_{i=1..j-1} (j-i)*d_i
           = (totalId - PId) - (j-1)*(totalD - PD) */
        idx_t suffixD  = totalD - PD;
        idx_t suffixId = totalId - PId;
        idx_t right = suffixId - (idx_t)(j - 1) * suffixD;

        if (left == right) return true;
    }
    return false;
}

/* Cache of sequence terms (stored in idx_t for safety) */
static idx_t *cache = NULL;
static size_t cache_len = 0;   /* number of stored terms */
static size_t cache_cap = 0;   /* allocated capacity */
static idx_t next_search_val = 1;   /* next integer to test */

/* Ensure the cache has room for at least one more element */
static void ensure_cache_capacity(void)
{
    if (cache_len >= cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 64;
        idx_t *tmp = (idx_t *)realloc(cache, new_cap * sizeof(idx_t));
        if (!tmp) abort();            /* fatal on memory failure */
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* Generate sequence terms until we have at least n terms stored */
static void fill_cache_to(idx_t n)
{
    while (cache_len < n) {
        if (is_fulcrum(next_search_val)) {
            ensure_cache_capacity();
            cache[cache_len++] = next_search_val;
        }
        ++next_search_val;
    }
}

/* Main sequence function requested by the build environment */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset handling */
    fill_cache_to(n);
    return (seq_t)cache[n - 1];
}
